result = await mcp.call_tool("tools", "ox-bridge-write", {"path": "/workspace/kmer.ts", "content": "// K-mer counter CLI: streams a FASTA file line-by-line with node:readline,
// counts plain (non-canonical) k-mers per record and globally using Maps,
// then prints the global top 10.

import { createReadStream } from "node:fs";
import { createInterface } from "node:readline";
import { pathToFileURL } from "node:url";

export const K = 8;

/** Count plain k-mers of a single sequence into the given Map (or a new one). */
export function countKmers(sequence: string, k: number, counts = new Map<string, number>()): Map<string, number> {
  for (let i = 0; i + k <= sequence.length; i++) {
    const km = sequence.slice(i, i + k);
    counts.set(km, (counts.get(km) ?? 0) + 1);
  }
  return counts;
}

export interface RunResult {
  /** Sum over all records of (recordLength - k + 1) */
  totalWindows: number;
  globalCounts: Map<string, number>;
}

/** Stream FASTA at `file`, count per-record and global k-mers. */
export async function run(file: string, k: number): Promise<RunResult> {
  let totalWindows = 0;
  const globalCounts = new Map<string, number>();

  const rl = createInterface({
    input: createReadStream(file, { encoding: "utf8" }),
    crlfDelay: Infinity,
  });

  let recordSeq = "";

  for await (const rawLine of rl) {
    const line = rawLine.trim();
    if (line.startsWith(">")) {
      if (recordSeq.length > 0) {
        countKmers(recordSeq, k, globalCounts);
        totalWindows += recordSeq.length - k + 1;
      }
      recordSeq = "";
    } else if (line.length > 0) {
      recordSeq += line;
    }
  }
  // final record
  if (recordSeq.length > 0) {
    countKmers(recordSeq, k, globalCounts);
    totalWindows += recordSeq.length - k + 1;
  }

  return { totalWindows, globalCounts };
}

async function main(): Promise<void> {
  const file = process.argv[2];
  if (!file) {
    console.error("usage: node --max-old-space-size=512 kmer.ts <fasta>");
    process.exit(1);
  }
  const t0 = Date.now();
  const { totalWindows, globalCounts } = await run(file, K);
  const elapsed = Date.now() - t0;

  // machine-readable line used by tests
  console.log(`TOTAL_WINDOWS\t${totalWindows}`);

  const top10 = [...globalCounts.entries()]
    .sort((a, b) => b[1] - a[1] || a[0].localeCompare(b[0]))
    .slice(0, 10);

  console.log(`Top ${top10.length} ${K}-mers:`);
  top10.forEach(([km, n], rank) => console.log(`${rank + 1}. ${km}\t${n}`));
  console.error(`done in ${elapsed} ms (${globalCounts.size} distinct ${K}-mers)`);
}

const invokedDirectly =
  process.argv[1] !== undefined &&
  import.meta.url === pathToFileURL(process.argv[1]).href;

if (invokedDirectly) {
  main().catch((err) => {
    console.error(err);
    process.exit(1);
  });
}
"})
