result = await mcp.call_tool("tools", "ox-bridge-write", {"path": "/workspace/kmer.test.ts", "content": "// Tests: correctness on a tiny example, global window-count invariant on the
// generated dataset, and a timed full run under a 512 MB heap budget.

import { describe, it, expect, beforeAll } from "vitest";
import { execFileSync } from "node:child_process";
import { existsSync } from "node:fs";

const FASTA = new URL("./sample.fasta", import.meta.url).pathname;
const EXPECTED_TOTAL = 50 * (100_000 - 7); // windows per record: len - k + 1
const BUDGET_MS = 10_000;

beforeAll(() => {
  if (!existsSync(FASTA)) {
    execFileSync("node", ["gen.ts"], { cwd: import.meta.dirname });
  }
});

describe("kmer counting", () => {
  it("counts plain 4-mers of 'ACGTACGT' correctly", async () => {
    const { countKmers } = await import("./kmer.ts");
    const counts = countKmers("ACGTACGT", 4);
    expect(counts.get("ACGT")).toBe(2);
    expect(counts.get("CGTA")).toBe(1);
    expect(counts.get("GTAC")).toBe(1);
    expect(counts.get("TACG")).toBe(1);
    expect(counts.size).toBe(4);
  });

  it("full run: total windows = 50 * (100000 - 7), under 10 s with 512 MB heap", () => {
    const t0 = Date.now();
    const stdout = execFileSync(
      "node",
      ["--max-old-space-size=512", "kmer.ts", FASTA],
      { cwd: import.meta.dirname, encoding: "utf8" },
    ).toString();
    const elapsed = Date.now() - t0;

    const totalMatch = stdout.match(/^TOTAL_WINDOWS\t(\d+)$/m);
    expect(totalMatch).not.toBeNull();
    expect(Number(totalMatch![1])).toBe(EXPECTED_TOTAL);

    expect(elapsed).toBeLessThan(BUDGET_MS);
    console.log(`timed run: ${elapsed} ms (budget ${BUDGET_MS} ms)`);
  });
});
"})
